"""Derived copies of recordings. Audio is generated by FFmpeg during the test."""

import json
import re
import uuid
from pathlib import Path

import pytest

from app.audio import ffmpeg, renditions
from tests.audio_fixtures import make_audio, requires_ffmpeg

NAME_IN_TAG = "Synthetic Speaker Name"


def test_each_kind_has_its_own_stable_parameters() -> None:
    hashes = {kind.params_sha256 for kind in (*renditions.AUDIO_KINDS, renditions.WAVEFORM)}
    assert len(hashes) == 4
    assert renditions.PLAYBACK_OPUS.params == {
        "format_version": 1,
        "ffmpeg_output_args": list(renditions.PLAYBACK_OPUS.output_args),
    }


def test_derived_files_sit_next_to_the_original_key() -> None:
    recording_id = uuid.uuid4()
    key = renditions.derived_key(f"2026/10/{recording_id}/original.webm", renditions.PLAYBACK_AAC)
    assert re.fullmatch(rf"2026/10/{recording_id}/playback_aac-[0-9a-f]{{16}}\.m4a", key)


@requires_ffmpeg
@pytest.mark.parametrize(
    ("kind", "codec", "rate"),
    [
        (renditions.ANALYSIS, "flac", 16000),
        (renditions.PLAYBACK_OPUS, "opus", 48000),
        (renditions.PLAYBACK_AAC, "aac", 44100),
    ],
)
def test_renditions_are_mono_untagged_and_repeatable(
    tmp_path: Path, kind: renditions.Kind, codec: str, rate: int
) -> None:
    source = tmp_path / "input"
    tag = ("-metadata", f"title={NAME_IN_TAG}", "-metadata", f"artist={NAME_IN_TAG}")
    make_audio(source, "mp3", seconds=2, rate=44100, channels=2, extra=tag)
    assert NAME_IN_TAG.encode() in source.read_bytes()

    first, second = tmp_path / "first", tmp_path / "second"
    for out in (first, second):
        ffmpeg.convert(source, "mp3", kind.output_args, out, timeout=60)
    assert first.read_bytes() == second.read_bytes()
    assert NAME_IN_TAG.encode() not in first.read_bytes()

    found = ffmpeg.probe(first, kind.extension, timeout=30)  # these extensions are containers
    assert found is not None
    [stream] = found.streams
    assert (stream.codec_name, stream.channels, stream.sample_rate_hz) == (codec, 1, rate)


@requires_ffmpeg
def test_waveform_peaks(tmp_path: Path) -> None:
    source, pcm = tmp_path / "input", tmp_path / "pcm"
    tone_then_silence = "sine=frequency=220:duration=1[a];anullsrc=d=1[b];[a][b]concat=v=0:a=1"
    make_audio(source, "wav", source=tone_then_silence)
    ffmpeg.convert(source, "wav", renditions.PCM_ARGS, pcm, timeout=60)

    document = json.loads(renditions.waveform(pcm))
    assert document["peaks_per_second"] == 20
    peaks = document["peaks"]
    assert len(peaks) == 40
    assert all(12 <= peak <= 13 for peak in peaks[:20])  # the tone peaks at 1/8 of full scale
    assert peaks[-10:] == [0] * 10
